<template><view class="page-content" :class="{'with-action':screen==='picking'}">
 <template v-if="screen==='workbench'">
  <view class="row between mb16"><view><text class="large-title">{{supplier?.name}}</text><text class="badge completed ml8">供应商</text><text class="small muted block mt8">专注食材供应 · 新鲜 · 安全 · 稳定</text></view><FIcon name="bell" :size="23"/></view>
  <view class="money-panel"><view class="row between small"><text>{{today()}}</text><text>仅显示负责门店</text></view><text class="large-title block mt16">早上好，今日订单待处理</text><text class="block mt8">待配送 {{activeOrders.length}} 单</text><view class="three-columns stats-inset mt16"><view v-for="s in summary" :key="s.value" @tap="go('supplierOrders',{filter:s.value})"><text class="huge-number">{{count(s.value)}}</text><text class="small">{{s.label}}</text></view></view></view>
  <view class="quick-actions standalone"><button v-for="a in actions" :key="a.label" @tap="go(a.screen,{filter:a.filter||''})"><FIcon :name="a.icon" :size="28"/><text>{{a.label}}</text></button></view><view class="section-head"><text class="h2">待处理订单</text><text class="small muted" @tap="go('supplierOrders')">查看全部 ›</text></view><OrderCard v-for="o in state.orders.filter(o=>['pending','preparing'].includes(o.status)).slice(0,4)" :key="o.id" :order="o"/><view v-if="!state.orders.some(o=>['pending','preparing'].includes(o.status))" class="empty"><FIcon name="check" :size="40"/><text>所有待处理订单已处理</text></view>
 </template>
 <template v-else-if="screen==='supplierOrders'">
  <view class="tabs scroll-tabs"><button v-for="s in tabs" :key="s.value" :class="{active:status===s.value}" @tap="status=s.value">{{s.label}}<text v-if="s.value" class="ml4">{{count(s.value)}}</text></button></view><Filters v-model:date="selectedDate" v-model:store="selectedStore"/><view class="search"><FIcon name="search" :size="18"/><input v-model="search" placeholder="搜索门店、订单编号" aria-label="搜索供应商订单"/></view><OrderCard v-for="o in filtered" :key="o.id" :order="o"/><view v-if="!filtered.length" class="empty"><FIcon name="order" :size="42"/><text>当前筛选下暂无订单</text><text class="small muted">门店下单后，负责订单会自动出现在这里</text></view>
 </template>
 <template v-else-if="screen==='picking'">
  <template v-if="order"><view class="row between"><text class="large-title">{{order.storeName}}</text><text class="badge" :class="order.status">{{statuses[order.status]}}</text></view><text class="small muted block mt12">订单号：{{order.order_no}}</text><text class="small muted block mt8">配送时间：{{order.delivery_date}} {{order.delivery_slot}}</text><view class="contact-strip row mt16"><FIcon name="user" :size="20"/><text class="grow">{{order.contact}}　{{order.phone}}</text><button class="icon-button" aria-label="联系门店" @tap="call(order.phone)"><FIcon name="phone"/></button></view>
  <view class="card mt16"><view class="row between"><text class="strong">食材清单（{{order.items.length}}）</text><text class="badge completed">已备齐 {{order.items.filter(i=>i.picked).length}} / {{order.items.length}} 种</text></view><view class="progress-track mt12"><view :style="{width:(order.items.filter(i=>i.picked).length/order.items.length*100)+'%'}"/></view><view v-for="i in order.items" :key="i.productId" class="item-row picking-row"><button class="check-circle" :class="{checked:i.picked}" :disabled="busy||order.status!=='preparing'" :aria-label="'备齐'+i.name" @tap="pick(i)"><text v-if="i.picked">✓</text></button><FoodPhoto :image="i.image"/><view class="grow"><text class="strong">{{i.name}}</text><text class="muted small block mt8">{{i.spec}} / {{i.unit}}</text></view><text class="strong">{{i.quantity}} {{i.unit}}</text></view></view>
  <view class="card"><text class="strong">配送信息</text><view class="row mt16"><FIcon name="pin"/><view class="grow"><text>{{order.address}}</text><text class="small muted block mt8">请送至指定收货处</text></view></view><view class="row mt16"><FIcon name="phone"/><text>{{order.contact}}　{{order.phone}}</text></view><view class="row mt16"><FIcon name="edit"/><text class="muted small">{{order.remark||'暂无特别备注，请按时配送'}}</text></view></view>
  <view v-if="order.status==='issue'" class="notice warning">异常已提交：{{order.issue}}，等待平台处理。</view><view v-else-if="!['completed','cancelled'].includes(order.status)" class="card"><text class="strong">缺货或配送异常</text><textarea v-model="issueNote" class="note-input" placeholder="填写具体问题，平台将跟进处理" maxlength="500"/><button class="btn secondary full mt8" :disabled="busy||!issueNote.trim()" @tap="report">上报异常</button></view>
  <view class="action-bar"><button class="btn secondary grow" @tap="call(order.phone)">联系门店</button><button v-if="nextAction" class="btn grow" :disabled="busy||!canPacked" @tap="advance">{{nextAction.label}}</button><text v-else class="badge" :class="order.status">{{statuses[order.status]}}</text></view></template><view v-else class="empty">订单不存在或无权访问</view>
 </template>
 <template v-else-if="screen==='delivery'">
  <view class="tabs"><button v-for="t in deliveryTabs" :key="t.value" :class="{active:status===t.value}" @tap="status=t.value">{{t.label}}</button></view><Filters v-model:date="selectedDate" v-model:store="selectedStore"/>
  <view class="delivery-summary"><view class="route-top">待履约 {{activeOrders.length}} 单 · {{state.stores.length}} 家负责门店</view><view class="route-stops"><view v-for="(s,i) in state.stores" :key="s.id" class="route-stop"><view class="stop-dot">{{i+1}}</view><text class="strong small">{{s.name}}</text></view><FIcon name="truck" :size="32"/></view></view>
  <view v-for="o in filtered" :key="o.id" class="card"><view class="row between"><text class="h2">{{o.storeName}}</text><text class="badge" :class="o.status">{{statuses[o.status]}}</text></view><text class="muted small block mt8">订单号：{{o.order_no}}</text><text class="muted small block mt8">配送时间：{{o.delivery_date}} {{o.delivery_slot}}</text><view class="row thumb-strip mt12"><FoodPhoto v-for="i in o.items.slice(0,4)" :key="i.productId" :image="i.image"/><text class="small muted">{{o.items.length}}种食材</text></view><view class="row mt16"><FIcon name="pin" :size="18"/><text class="small grow">{{o.address}}</text></view><view class="row mt8"><FIcon name="user" :size="18"/><text class="small grow">{{o.contact}}　{{o.phone}}</text><button class="icon-button" aria-label="拨打门店电话" @tap="call(o.phone)"><FIcon name="phone" :size="19"/></button></view><view class="row mt16"><button class="btn secondary small-btn grow" @tap="navigation(o.address)"><FIcon name="pin" :size="16"/>复制收货地址</button><button v-if="o.status==='ready'||o.status==='delivering'" class="btn small-btn grow" :disabled="busy" @tap="deliveryAction(o)">{{o.status==='ready'?'开始配送':'确认送达'}}</button><button v-else class="btn secondary small-btn grow" @tap="go('picking',{id:o.id})">配送详情</button></view></view><view v-if="!filtered.length" class="empty"><FIcon name="truck" :size="42"/><text>暂无相关配送任务</text></view>
 </template>
 <template v-else-if="screen==='history'">
  <view class="row mb16"><picker mode="date" :value="dateFrom" @change="dateFrom=$event.detail.value"><view class="filter-pill">{{dateFrom}} 起</view></picker><picker mode="date" :value="dateTo" @change="dateTo=$event.detail.value"><view class="filter-pill">至 {{dateTo}}</view></picker><picker :range="storeOptions" range-key="name" :value="Math.max(0,storeOptions.findIndex(s=>s.id===selectedStore))" @change="selectedStore=storeOptions[$event.detail.value].id"><view class="filter-pill">{{storeOptions.find(s=>s.id===selectedStore)?.name}}⌄</view></picker></view><view class="money-panel two-columns"><view><text class="small">已完成</text><text class="huge-number block mt8">{{historyOrders.length}} <text class="unit">单</text></text></view><view><text class="small">配送门店</text><text class="huge-number block mt8">{{new Set(historyOrders.map(o=>o.store_id)).size}} <text class="unit">家</text></text></view></view><view class="tabs"><button :class="{active:historyTab==='orders'}" @tap="historyTab='orders'">订单记录</button><button :class="{active:historyTab==='stock'}" @tap="historyTab='stock'">食材汇总</button></view><template v-if="historyTab==='stock'"><view class="card"><view class="row between muted small"><text>食材</text><text>累计配送</text></view><view v-for="i in stock" :key="i.productId+':'+i.unit" class="item-row"><FoodPhoto :image="i.image"/><text class="grow">{{i.name}}</text><text class="strong">{{i.quantity}} {{i.unit}}</text></view><view v-if="!stock.length" class="empty">此时间范围内还没有已完成订单</view></view></template><template v-else><OrderCard v-for="o in historyOrders" :key="o.id" :order="o"/><view v-if="!historyOrders.length" class="empty">暂无已完成订单</view></template><button class="btn secondary full" :disabled="busy" @tap="download"><FIcon name="download" :size="18"/>导出明细</button>
 </template>
</view></template>
<script setup>
import {ref,computed,inject} from 'vue';import FIcon from './FIcon.vue';import FoodPhoto from './FoodPhoto.vue';import OrderCard from './OrderCard.vue';import Filters from './SupplierFilters.vue';import {state,go,mutate,confirm,today,statuses,call,navigation,exportFile,responsibleStores} from '../lib/food'
const props=defineProps({screen:String,itemId:String,filter:String});const {run,busy}=inject('app');const supplier=computed(()=>state.suppliers.find(s=>s.id===state.user?.supplierId));const summary=[{value:'pending',label:'待接单'},{value:'preparing',label:'待备货'},{value:'delivering',label:'配送中'}];const count=s=>state.orders.filter(o=>o.status===s).length;const activeOrders=computed(()=>state.orders.filter(o=>['ready','delivering'].includes(o.status)));const actions=[{screen:'supplierOrders',label:'接单处理',icon:'order',filter:'pending'},{screen:'supplierOrders',label:'备货清单',icon:'box',filter:'preparing'},{screen:'delivery',label:'配送任务',icon:'truck'},{screen:'history',label:'历史汇总',icon:'chart'}];
const status=ref(props.filter||(props.screen==='delivery'?'ready':props.screen==='supplierOrders'?'pending':'')),selectedDate=ref(''),selectedStore=ref(0),search=ref('');const storeOptions=computed(()=>[{id:0,name:'全部负责门店'},...responsibleStores()]);const tabs=[{value:'',label:'全部'},{value:'pending',label:'待接单'},{value:'preparing',label:'待备货'},{value:'ready',label:'待配送'},{value:'delivering',label:'配送中'},{value:'delivered',label:'待收货'},{value:'completed',label:'已完成'},{value:'issue',label:'异常'}];const deliveryTabs=[{value:'ready',label:'待配送'},{value:'delivering',label:'配送中'},{value:'delivered',label:'待收货'},{value:'completed',label:'已完成'}];const filtered=computed(()=>state.orders.filter(o=>(!status.value||o.status===status.value)&&(!selectedDate.value||String(o.delivery_date).startsWith(selectedDate.value))&&(!selectedStore.value||o.store_id===selectedStore.value)&&(!search.value||o.storeName.includes(search.value)||o.order_no.includes(search.value))));
const order=computed(()=>state.orders.find(o=>String(o.id)===props.itemId));const nextAction=computed(()=>({pending:{code:'accept',label:'确认接单'},preparing:{code:'packed',label:'备货完成'},ready:{code:'start',label:'开始配送'},delivering:{code:'deliver',label:'确认送达'}})[order.value?.status]);const canPacked=computed(()=>order.value?.status!=='preparing'||order.value.items.every(i=>i.picked)),issueNote=ref('');
const dateFrom=ref(today().slice(0,8)+'01'),dateTo=ref(today()),historyTab=ref('stock');const historyOrders=computed(()=>state.orders.filter(o=>o.status==='completed'&&String(o.created_at).slice(0,10)>=dateFrom.value&&String(o.created_at).slice(0,10)<=dateTo.value&&(!selectedStore.value||o.store_id===selectedStore.value)));const stock=computed(()=>{const map={};for(const o of historyOrders.value)for(const i of o.items){const k=i.productId+':'+i.unit;if(!map[k])map[k]={...i,quantity:0};map[k].quantity=Math.round((map[k].quantity+Number(i.quantity))*100)/100}return Object.values(map)});
function pick(i){run(()=>mutate('/orders/'+order.value.id+'/picking',{productId:i.productId,picked:!i.picked},''))}
function advance(){run(async()=>{if(await confirm(nextAction.value.label+'？'))await mutate('/orders/'+order.value.id+'/action',{action:nextAction.value.code},'订单状态已同步')})}
function report(){run(async()=>{await mutate('/orders/'+order.value.id+'/action',{action:'report',note:issueNote.value},'异常已上报平台');issueNote.value=''})}
function deliveryAction(o){run(async()=>{const action=o.status==='ready'?'start':'deliver';if(await confirm(action==='start'?'开始配送？':'确认已送达门店？'))await mutate('/orders/'+o.id+'/action',{action},'配送状态已同步')})}
function download(){run(()=>exportFile(historyTab.value==='stock'?'stock':'orders',{from:dateFrom.value,to:dateTo.value,storeId:selectedStore.value||'',status:'completed'}))}
// The filter UI is native uni-app markup in a shared component below.
</script>

